function Breadcrumbs({ parent, current, currentPath }: { parent: { label: string; href: string }; current: string; currentPath: string }) {
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: siteUrl },
      { '@type': 'ListItem', position: 2, name: parent.label, item: `${siteUrl}${parent.href}` },
      { '@type': 'ListItem', position: 3, name: current, item: `${siteUrl}${currentPath}` },
    ],
  }

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, '\\u003c') }}
      />
      <nav aria-label="Breadcrumb" className="mb-7">
        <ol className="flex flex-wrap items-center gap-2 text-xs text-text-muted">
          <li><Link href="/" className="hover:text-text-primary">Home</Link></li>
          <li aria-hidden="true">/</li>
          <li><Link href={parent.href} className="hover:text-text-primary">{parent.label}</Link></li>
          <li aria-hidden="true">/</li>
          <li aria-current="page" className="text-text-primary">{current}</li>
        </ol>
      </nav>
    </>
  )
}

function getDetailPath(parentHref: string, consultationPath: string) {
  const query = consultationPath.split('?')[1] ?? ''
  const parameter = parentHref === '/solutions' ? 'interest' : 'industry'
  const slug = new URLSearchParams(query).get(parameter)
  return slug ? `${parentHref}/${slug}` : parentHref
}

function ServiceJsonLd({ name, description, path }: { name: string; description: string; path: string }) {
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Service',
    '@id': `${absoluteUrl(path)}#service`,
    name,
    serviceType: name,
    description,
    url: absoluteUrl(path),
    provider: { '@id': `${siteUrl}/#organization` },
    areaServed: [
      { '@type': 'Country', name: 'United States' },
      { '@type': 'Country', name: 'Canada' },
    ],
  }

  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, '\\u003c') }} />
}

function TemplateHero({ eyebrow, title, description, label, parent, current, consultationPath, visual }: { eyebrow: string; title: string; description: string; label: string; parent: { label: string; href: string }; current: string; consultationPath: string; visual?: IndustryVisual }) {
  const currentPath = getDetailPath(parent.href, consultationPath)

  return (
    <section className="relative overflow-hidden border-b border-border-subtle bg-background-secondary">
      {parent.href === '/solutions' ? <ServiceJsonLd name={current} description={description} path={currentPath} /> : null}
      <div className="pointer-events-none absolute left-1/2 top-0 h-72 w-[48rem] -translate-x-1/2 rounded-full bg-brand-primary/10 blur-3xl" aria-hidden="true" />
      <div className="relative mx-auto max-w-7xl px-5 py-14 sm:px-8 sm:py-20 lg:px-10 lg:py-24">
        <Breadcrumbs parent={parent} current={current} currentPath={currentPath} />
        <div className={visual ? 'grid items-center gap-10 lg:grid-cols-[1.05fr_0.95fr] lg:gap-14' : undefined}>
          <div className={visual ? 'max-w-3xl' : 'max-w-4xl'}>
            <p className="eyebrow">{eyebrow}</p>
            <div className="mt-4">
              <h1 className="text-balance text-4xl font-semibold leading-tight tracking-tight text-text-primary sm:text-5xl lg:text-6xl">{title}</h1>
              <p className="mt-6 max-w-2xl text-base leading-7 text-text-secondary sm:text-lg">{description}</p>
              <Button className="mt-8" variant="brand" asChild>
                <Link href={consultationPath} aria-label={`Request a consultation about ${label}`}>
                  Request a Consultation <ArrowRight className="h-4 w-4" aria-hidden="true" />
                </Link>
              </Button>
            </div>
          </div>
          {visual ? <IndustryImage visual={visual} preload /> : null}
        </div>
      </div>
    </section>
  )
}

export function SolutionPageTemplate({ content, current, consultationPath = '/consultation' }: { content: SolutionContent; current: string; consultationPath?: string }) { return <main id="main-content"><TemplateHero eyebrow={content.eyebrow} title={content.title} description={content.description} label="workflow" parent={{ label: 'Solutions', href: '/solutions' }} current={current} consultationPath={consultationPath} /><Section background="muted"><div className="grid gap-10 lg:grid-cols-[0.75fr_1.25fr] lg:gap-16"><div><p className="eyebrow">Why it matters</p><h2 className="mt-3 text-3xl font-semibold tracking-tight text-text-primary">{content.outcome}</h2></div><p className="max-w-2xl text-lg leading-8 text-text-secondary">{solutionScopeCopy[current] ?? 'A useful workflow has clearly defined knowledge, permitted actions, limits, and a person who owns exceptions.'}</p></div></Section><Section><SectionHeading align="left" label="Capabilities" title="What the agent can do—and where it stops" /><div className="grid gap-5 lg:grid-cols-2"><div className="rounded-[var(--radius-xl)] border border-brand-primary/25 bg-brand-primary/[0.04] p-6"><h3 className="text-xl font-semibold text-text-primary">Within scope</h3><ul className="mt-5 space-y-3">{content.does.map((item) => <li key={item} className="flex gap-2 text-sm leading-6 text-text-secondary"><Check className="mt-1 h-4 w-4 shrink-0 text-brand-primary" aria-hidden="true" />{item}</li>)}</ul></div><div className="rounded-[var(--radius-xl)] border border-border-subtle bg-surface-primary p-6"><h3 className="text-xl font-semibold text-text-primary">The agent will not:</h3><ul className="mt-5 space-y-3">{content.doesNot.map((item) => <li key={item} className="flex gap-2 text-sm leading-6 text-text-secondary"><CircleAlert className="mt-1 h-4 w-4 shrink-0 text-amber-600" aria-hidden="true" />{item}</li>)}</ul></div></div></Section><Section background="muted"><SectionHeading label="Workflow" title="A visible path from conversation to action" description="The exact actions depend on systems, permissions, and business rules confirmed during implementation." /><WorkflowRail items={content.workflow} /></Section><Section><SectionHeading align="left" label="Use cases" title="Where this pattern can help" /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{content.useCases.map((item) => <article key={item.title} className="rounded-[var(--radius-lg)] border border-border-subtle bg-surface-primary p-5 shadow-soft"><h3 className="font-semibold text-text-primary">{item.title}</h3><p className="mt-2 text-sm leading-6 text-text-secondary">{item.description}</p></article>)}</div></Section><Section background="muted"><div className="grid gap-10 lg:grid-cols-2"><div><SectionHeading align="left" label="Integrations" title="Connected only where access is appropriate" description="Available integrations depend on the actual software, APIs, authentication, permissions, and data mapping." /></div><div className="grid gap-3 sm:grid-cols-2">{content.integrations.map((item) => <div key={item} className="flex items-center gap-3 rounded-[var(--radius-md)] border border-border-subtle bg-surface-primary p-4 text-sm font-medium text-text-primary"><Workflow className="h-4 w-4 text-brand-primary" aria-hidden="true" />{item}</div>)}</div></div></Section><RelatedLinks links={solutionRelated[current] ?? []} /><FaqSection items={content.faq} /><FinalCtaSection /></main> }

export function IndustryPageTemplate({ content, current, consultationPath = '/consultation' }: { content: IndustryContent; current: string; consultationPath?: string }) { return <main id="main-content"><TemplateHero eyebrow={content.eyebrow} title={content.title} description={content.description} label="this workflow" parent={{ label: 'Industries', href: '/industries' }} current={current} consultationPath={consultationPath} visual={getIndustryVisual(current)} /><Section background="muted"><SectionHeading label="Common problems" title={industryHeadings[current]?.problems ?? 'Where your team loses time'} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{content.problems.map((problem) => <div key={problem} className="rounded-[var(--radius-lg)] border border-border-subtle bg-surface-primary p-5 text-sm leading-6 text-text-secondary">{problem}</div>)}</div></Section><Section><SectionHeading align="left" label="Recommended systems" title={industryHeadings[current]?.systems ?? 'Start with the customer moments that need structure'} /><div className="grid gap-5 lg:grid-cols-3">{content.systems.map(({ title, description }, index) => <article key={title} className="rounded-[var(--radius-lg)] border border-border-subtle bg-surface-primary p-6 shadow-soft"><span className="eyebrow">0{index + 1}</span><h3 className="mt-4 text-xl font-semibold text-text-primary">{title}</h3><p className="mt-2 text-sm leading-6 text-text-secondary">{description}</p></article>)}</div></Section><Section background="muted"><div className="grid items-start gap-8 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16"><div><SectionHeading align="left" label="Example conversation" title={industryHeadings[current]?.conversation ?? 'Useful context before a team member gets involved'} description="This is an illustrative scenario, not a claim about live production behavior." /></div><div className="space-y-3 rounded-[var(--radius-xl)] border border-border-subtle bg-surface-primary p-5 shadow-soft sm:p-6">{content.conversation.map(({ speaker, text }) => <div key={speaker} className="rounded-[var(--radius-md)] bg-background-secondary p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-brand-hover">{speaker}</p><p className="mt-1 text-sm leading-6 text-text-primary">{text}</p></div>)}</div></div></Section><Section><SectionHeading label="Example workflow" title={industryHeadings[current]?.workflow ?? 'From customer request to the right team member'} /><WorkflowRail items={content.workflow} /></Section><Section background="muted"><div className="grid gap-10 lg:grid-cols-2"><div><SectionHeading align="left" label="Industry considerations" title={industryHeadings[current]?.boundaries ?? 'Keep important decisions with people'} /></div><ul className="space-y-4">{content.considerations.map((item) => <li key={item} className="flex gap-3 text-sm leading-6 text-text-secondary"><ShieldCheck className="mt-1 h-4 w-4 shrink-0 text-brand-primary" aria-hidden="true" />{item}</li>)}</ul></div><div className="mt-10 flex flex-wrap gap-3">{content.integrations.map((item) => <span key={item} className="inline-flex items-center gap-2 rounded-full border border-border-subtle bg-surface-primary px-3 py-2 text-xs font-semibold text-text-secondary"><Home className="h-3.5 w-3.5 text-brand-primary" aria-hidden="true" />{item}</span>)}</div></Section><RelatedLinks links={industryRelated[current] ?? []} /><FaqSection items={content.faq} /><FinalCtaSection /></main> }
